import 'package:family_veda/models/family_dashboard.dart';
import 'package:flutter_test/flutter_test.dart';

/// Head vs Adult card-visibility rule under test in the home screen: the
/// "Join requests" card only renders when [FamilyDashboard.isHead] is true
/// AND there is at least one pending request.
bool shouldShowJoinRequestsCard(FamilyDashboard dashboard) =>
    dashboard.isHead && dashboard.pendingJoinRequests > 0;

void main() {
  test('parses Head dashboard with family code and pending join requests', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'Head',
      'familyId': 'fam-1',
      'familyName': 'The Silvas',
      'familyCode': 'FV-ABCDEF',
      'memberCount': 4,
      'minorCount': 2,
      'pendingJoinRequests': 3,
      'openCases': 1,
      'approvedGuidanceCount': 2,
      'unreadNotifications': 5,
    });

    expect(dashboard.isHead, isTrue);
    expect(dashboard.familyCode, 'FV-ABCDEF');
    expect(dashboard.pendingJoinRequests, 3);
    expect(dashboard.memberCount, 4);
    expect(dashboard.minorCount, 2);
  });

  test('parses Adult dashboard without Head-only fields', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'AdultMember',
      'familyId': 'fam-1',
      'memberCount': 4,
      'minorCount': 2,
      'openCases': 0,
      'approvedGuidanceCount': 1,
      'unreadNotifications': 0,
    });

    expect(dashboard.isHead, isFalse);
    expect(dashboard.familyCode, isNull);
    expect(dashboard.pendingJoinRequests, 0);
  });

  test('parses nested nextAppointment and familyDoctor', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'AdultMember',
      'memberCount': 1,
      'minorCount': 0,
      'openCases': 0,
      'approvedGuidanceCount': 0,
      'unreadNotifications': 0,
      'nextAppointment': {
        'id': 'appt-1',
        'memberId': 'mem-1',
        'startsAt': '2026-10-01T10:00:00Z',
        'durationMinutes': 30,
        'reason': 'Checkup',
        'status': 'Confirmed',
      },
      'familyDoctor': {'id': 'doc-1', 'displayName': 'Jane Perera'},
    });

    expect(dashboard.nextAppointment?.id, 'appt-1');
    expect(dashboard.familyDoctor?.displayName, 'Jane Perera');
  });

  test('Head with pending requests sees the join-requests card', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'Head',
      'memberCount': 1,
      'minorCount': 0,
      'pendingJoinRequests': 1,
      'openCases': 0,
      'approvedGuidanceCount': 0,
      'unreadNotifications': 0,
    });
    expect(shouldShowJoinRequestsCard(dashboard), isTrue);
  });

  test('Adult never sees the join-requests card', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'AdultMember',
      'memberCount': 1,
      'minorCount': 0,
      'pendingJoinRequests': 5,
      'openCases': 0,
      'approvedGuidanceCount': 0,
      'unreadNotifications': 0,
    });
    expect(shouldShowJoinRequestsCard(dashboard), isFalse);
  });

  test('Head with zero pending requests does not see the card', () {
    final dashboard = FamilyDashboard.fromJson({
      'role': 'Head',
      'memberCount': 1,
      'minorCount': 0,
      'pendingJoinRequests': 0,
      'openCases': 0,
      'approvedGuidanceCount': 0,
      'unreadNotifications': 0,
    });
    expect(shouldShowJoinRequestsCard(dashboard), isFalse);
  });
}
